        ) VALUES (
            '79afa1cd-ce05-4fff-8325-0fd16185c74c', 'SSC CGL 2025 Tier I Shift 3', 2025, 'Shift 3', 'Quantitative Aptitude', 32,
            'Order these classical dance forms by their earliest documented mentions (earliest first): 
1. Bharatanatyam 
